function sumSubseqWidths(nums) {
  const MOD = 1000000007;
  const n = nums.length;
  nums.sort((a, b) => a - b);
  const pow2 = [1];
  for (let i = 1; i < n; i++) {
    pow2.push((pow2[i - 1] * 2) % MOD);
  }
  let total = 0;
  for (let i = 0; i < n; i++) {
    const asMax = pow2[i];
    const asMin = pow2[n - 1 - i];
    total = (total + nums[i] * (asMax - asMin + MOD)) % MOD;
  }
  return total;
}

