function sumSubseqWidths(nums) {
  // Try every non-empty set of positions and add its max minus its min.
  let sum = 0;
  for (let mask = 1; mask < (1 << nums.length); mask++) {
    let low = Infinity;
    let high = -Infinity;
    for (let bit = 0; bit < nums.length; bit++) {
      if (mask & (1 << bit)) {
        low = Math.min(low, nums[bit]);
        high = Math.max(high, nums[bit]);
      }
    }
    sum += high - low;
  }
  return sum % 1000000007;
}

